content:
Use one of these.

1) Without code  
File → Scripts → Load Files into Stack… → Browse and select the 4 pass files (order = bottom→top) → OK.  
File → Save As… → PSD (or PSB if >2 GB).  
For layered EXR, save via an EXR plugin that supports layers (e.g., ProEXR/EXR-IO) and enable “save layers.”

2) One-click script (stacks any 4 files you pick, then saves layered PSD/PSB)
Save as `StackPasses.jsx`, run via File → Scripts → Browse….

```jsx
#target photoshop
app.displayDialogs = DialogModes.NO;

(function () {
    // Select passes (pick 4; order = bottom→top)
    var files = File.openDialog(
        "Select your 4 pass images (bottom→top order)",
        "Images:*.psd;*.psb;*.exr;*.tif;*.tiff;*.png;*.jpg",
        true
    );
    if (!files || !files.length) return;

    function layerNameOf(f) { return decodeURI(f.displayName).replace(/\.[^\.]+$/, ""); }

    // Open first file as the base doc
    var base = app.open(files[0]);
    var doc  = base;
    doc.activeLayer.name = layerNameOf(files[0]);

    // Add the rest as layers
    for (var i = 1; i < files.length; i++) {
        var src = app.open(files[i]);
        try {
            // Ensure single layer for duplication
            if (src.layers && src.layers.length > 1) src.flatten();
            src.activeLayer.name = layerNameOf(files[i]);
            // Duplicate into target doc (placed at top)
            src.activeLayer.duplicate(doc, ElementPlacement.PLACEATBEGINNING);
        } finally {
            src.close(SaveOptions.DONOTSAVECHANGES);
        }
    }

    // Optional: put layers into a group called PASSES
    var grp = doc.layerSets.add();
    grp.name = "PASSES";
    while (doc.layers.length > 1) {
        doc.layers[0].move(grp, ElementPlacement.INSIDE);
    }

    // Save layered file
    var out = File.saveDialog("Save layered file as PSD/PSB", "PSD:*.psd;PSB:*.psb");
    if (!out) return;

    if (/\.psb$/i.test(out.name)) {
        var psb = new LargeDocumentFormatSaveOptions();
        psb.layers = true;
        psb.embedColorProfile = true;
        doc.saveAs(out, psb, true, Extension.LOWERCASE);
    } else {
        var psd = new PhotoshopSaveOptions();
        psd.layers = true;
        psd.embedColorProfile = true;
        doc.saveAs(out, psd, true, Extension.LOWERCASE);
    }

    // If you have a layered-EXR plugin installed, you can also save an EXR copy:
    // try {
    //     var exrFile = new File(out.fsName.replace(/\.(psd|psb)$/i, ".exr"));
    //     var exrOpts = new OpenEXROptions();   // Provided by ProEXR/EXR-IO
    //     exrOpts.layers = true;
    //     doc.saveAs(exrFile, exrOpts, true, Extension.LOWERCASE);
    // } catch (e) { /* EXR plugin not available; skip */ }

})();
```

Notes: The script preserves each pass as its own layer, names layers from filenames, nests them under a “PASSES” group, and saves one layered file. For EXR with layers, a plugin that exposes `OpenEXROptions` is required.
